import{_ as l,a0 as t,w as r,s as o,I as a,x as n,a1 as e,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Linux 上以树状查看文件和进程 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上以树状查看文件和进程 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上以树状查看文件和进程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上以树状查看文件和进程 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191010 Viewing files and processes as trees on Linux","title":"在 Linux 上以树状查看文件和进程","tag":"201910","desc":""},"relativePath":"201910/20191010 Viewing files and processes as trees on Linux.md","filePath":"[post].md"}'),c={name:"201910/20191010 Viewing files and processes as trees on Linux.md"};function h(u,s,g,k,b,f){const p=t("Link");return r(),o("div",null,[s[23]||(s[23]=a("h1",{id:"在-linux-上以树状查看文件和进程",tabindex:"-1"},[n("在 Linux 上以树状查看文件和进程 "),a("a",{class:"header-anchor",href:"#在-linux-上以树状查看文件和进程","aria-label":"Permalink to “在 Linux 上以树状查看文件和进程”"},"​")],-1)),s[24]||(s[24]=a("blockquote",null,[a("p",null,"介绍三个 Linux 命令：ps、pstree 和 tree 以类似树的格式查看文件和进程。")],-1)),s[25]||(s[25]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/201910/15/093202rwm5k9pnpntgbtpr.jpg",alt:""})],-1)),a("p",null,[e(p,{href:"https://www.networkworld.com/article/3215226/what-is-linux-uses-featres-products-operating-systems.html"},{default:i(()=>[...s[0]||(s[0]=[n("Linux",-1)])]),_:1}),s[1]||(s[1]=n(" 提供了一些方便的命令，用于以树状分支形式查看文件和进程，从而易于查看它们之间的关系。在本文中，我们将介绍 ",-1)),s[2]||(s[2]=a("code",null,"ps",-1)),s[3]||(s[3]=n("、",-1)),s[4]||(s[4]=a("code",null,"pstree",-1)),s[5]||(s[5]=n(" 和 ",-1)),s[6]||(s[6]=a("code",null,"tree",-1)),s[7]||(s[7]=n(" 命令以及它们提供的一些选项，这些选项可帮助你将注意力集中在要查看的内容上。",-1))]),s[26]||(s[26]=d(`<h3 id="ps" tabindex="-1">ps <a class="header-anchor" href="#ps" aria-label="Permalink to “ps”">​</a></h3><p>我们用来列出进程的 <code>ps</code> 命令有一些有趣的选项，但是很多人从来没有利用过。虽然常用的 <code>ps -ef</code> 提供了正在运行的进程的完整列表，但是 <code>ps -ejH</code> 命令增加了一个不错的效果。它缩进了相关的进程以使这些进程之间的关系在视觉上更加清晰——就像这个片段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ejH</span></span>
<span class="line"><span>  PID  PGID   SID TTY          TIME CMD</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span> 1396  1396  1396 ?        00:00:00   sshd</span></span>
<span class="line"><span>28281 28281 28281 ?        00:00:00     sshd</span></span>
<span class="line"><span>28409 28281 28281 ?        00:00:00       sshd</span></span>
<span class="line"><span>28410 28410 28410 pts/0    00:00:00         bash</span></span>
<span class="line"><span>30968 30968 28410 pts/0    00:00:00           ps</span></span></code></pre></div><p>可以看到，正在运行的 <code>ps</code> 进程是在 <code>bash</code> 中运行的，而 <code>bash</code> 是在 ssh 会话中运行的。</p><p><code>-exjf</code> 选项字符串提供了类似的视图，但是带有一些其它细节和符号以突出显示进程的层次结构性质：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -exjf</span></span>
<span class="line"><span>PPID   PID  PGID   SID TTY      TPGID STAT   UID   TIME COMMAND</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>    1  1396  1396  1396 ?           -1 Ss       0   0:00 /usr/sbin/sshd -D</span></span>
<span class="line"><span> 1396 28281 28281 28281 ?           -1 Ss       0   0:00  \\_ sshd: shs [priv]</span></span>
<span class="line"><span>28281 28409 28281 28281 ?           -1 S     1000   0:00      \\_ sshd: shs@pts/0</span></span>
<span class="line"><span>28409 28410 28410 28410 pts/0    31028 Ss    1000   0:00          \\_ -bash</span></span>
<span class="line"><span>28410 31028 31028 28410 pts/0    31028 R+    1000   0:00              \\_ ps axjf</span></span></code></pre></div><p>命令中使用的这些选项表示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-e  选择所有进程</span></span>
<span class="line"><span>-j  使用工作格式</span></span>
<span class="line"><span>-f  提供完整格式列表</span></span>
<span class="line"><span>-H  分层显示进程（如，树状格式）</span></span>
<span class="line"><span>-x  取消“必须与 tty 相关联”的限制</span></span></code></pre></div><p>同时，该命令也有一个 <code>--forest</code> 选项提供了类似的视图。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef --forest</span></span>
<span class="line"><span>UID        PID  PPID  C STIME TTY          TIME CMD</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>root      1396     1  0 Oct08 ?        00:00:00 /usr/sbin/sshd -D</span></span>
<span class="line"><span>root     28281  1396  0 12:55 ?        00:00:00  \\_ sshd: shs [priv]</span></span>
<span class="line"><span>shs      28409 28281  0 12:56 ?        00:00:00      \\_ sshd: shs@pts/0</span></span>
<span class="line"><span>shs      28410 28409  0 12:56 pts/0    00:00:00          \\_ -bash</span></span>
<span class="line"><span>shs      32351 28410  0 14:39 pts/0    00:00:00              \\_ ps -ef --forest</span></span></code></pre></div><p>注意，这些示例只是这些命令如何使用的示例。你可以选择最适合你的进程视图的任何选项组合。</p><h3 id="pstree" tabindex="-1">pstree <a class="header-anchor" href="#pstree" aria-label="Permalink to “pstree”">​</a></h3><p>使用 <code>pstree</code> 命令可以获得类似的进程视图。尽管 <code>pstree</code> 具备了许多选项，但是该命令本身就提供了非常有用的显示。注意，许多父子进程关系显示在单行而不是后续行上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pstree</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>        ├─sshd───sshd───sshd───bash───pstree</span></span>
<span class="line"><span>        ├─systemd─┬─(sd-pam)</span></span>
<span class="line"><span>        │         ├─at-spi-bus-laun─┬─dbus-daemon</span></span>
<span class="line"><span>        │         │                 └─3*[{at-spi-bus-laun}]</span></span>
<span class="line"><span>        │         ├─at-spi2-registr───2*[{at-spi2-registr}]</span></span>
<span class="line"><span>        │         ├─dbus-daemon</span></span>
<span class="line"><span>        │         ├─ibus-portal───2*[{ibus-portal}]</span></span>
<span class="line"><span>        │         ├─pulseaudio───2*[{pulseaudio}]</span></span>
<span class="line"><span>        │         └─xdg-permission-───2*[{xdg-permission-}]</span></span></code></pre></div><p>通过 <code>-n</code> 选项，<code>pstree</code> 以数值（按进程 ID）顺序显示进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pstree -n</span></span>
<span class="line"><span>systemd─┬─systemd-journal</span></span>
<span class="line"><span>        ├─systemd-udevd</span></span>
<span class="line"><span>        ├─systemd-timesyn───{systemd-timesyn}</span></span>
<span class="line"><span>        ├─systemd-resolve</span></span>
<span class="line"><span>        ├─systemd-logind</span></span>
<span class="line"><span>        ├─dbus-daemon</span></span>
<span class="line"><span>        ├─atopacctd</span></span>
<span class="line"><span>        ├─irqbalance───{irqbalance}</span></span>
<span class="line"><span>        ├─accounts-daemon───2*[{accounts-daemon}]</span></span>
<span class="line"><span>        ├─acpid</span></span>
<span class="line"><span>        ├─rsyslogd───3*[{rsyslogd}]</span></span>
<span class="line"><span>        ├─freshclam</span></span>
<span class="line"><span>        ├─udisksd───4*[{udisksd}]</span></span>
<span class="line"><span>        ├─networkd-dispat</span></span>
<span class="line"><span>        ├─ModemManager───2*[{ModemManager}]</span></span>
<span class="line"><span>        ├─snapd───10*[{snapd}]</span></span>
<span class="line"><span>        ├─avahi-daemon───avahi-daemon</span></span>
<span class="line"><span>        ├─NetworkManager───2*[{NetworkManager}]</span></span>
<span class="line"><span>        ├─wpa_supplicant</span></span>
<span class="line"><span>        ├─cron</span></span>
<span class="line"><span>        ├─atd</span></span>
<span class="line"><span>        ├─polkitd───2*[{polkitd}]</span></span>
<span class="line"><span>        ├─colord───2*[{colord}]</span></span>
<span class="line"><span>        ├─unattended-upgr───{unattended-upgr}</span></span>
<span class="line"><span>        ├─sshd───sshd───sshd───bash───pstree</span></span></code></pre></div><p>使用 <code>pstree</code> 时可以考虑的一些选项包括 <code>-a</code>（包括命令行参数）和 <code>-g</code>（包括进程组）。</p><p>以下是一些简单的示例（片段）。</p><p>命令 <code>pstree -a</code> 的输出内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>└─wpa_supplicant -u -s -O /run/wpa_supplicant</span></span></code></pre></div><p>命令 <code>pstree -g</code> 的输出内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>├─sshd(1396)───sshd(28281)───sshd(28281)───bash(28410)───pstree(1115)</span></span></code></pre></div><h3 id="tree" tabindex="-1">tree <a class="header-anchor" href="#tree" aria-label="Permalink to “tree”">​</a></h3><p>虽然 <code>tree</code> 命令听起来与 <code>pstree</code> 非常相似，但这是用于查看文件而非进程的命令。它提供了一个漂亮的树状目录和文件视图。</p><p>如果你使用 <code>tree</code> 命令查看 <code>/proc</code> 目录，你显示的开头部分将类似于这个：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree /proc</span></span>
<span class="line"><span>/proc</span></span>
<span class="line"><span>├── 1</span></span>
<span class="line"><span>│   ├── attr</span></span>
<span class="line"><span>│   │   ├── apparmor</span></span>
<span class="line"><span>│   │   │   ├── current</span></span>
<span class="line"><span>│   │   │   ├── exec</span></span>
<span class="line"><span>│   │   │   └── prev</span></span>
<span class="line"><span>│   │   ├── current</span></span>
<span class="line"><span>│   │   ├── display</span></span>
<span class="line"><span>│   │   ├── exec</span></span>
<span class="line"><span>│   │   ├── fscreate</span></span>
<span class="line"><span>│   │   ├── keycreate</span></span>
<span class="line"><span>│   │   ├── prev</span></span>
<span class="line"><span>│   │   ├── smack</span></span>
<span class="line"><span>│   │   │   └── current</span></span>
<span class="line"><span>│   │   └── sockcreate</span></span>
<span class="line"><span>│   ├── autogroup</span></span>
<span class="line"><span>│   ├── auxv</span></span>
<span class="line"><span>│   ├── cgroup</span></span>
<span class="line"><span>│   ├── clear_refs</span></span>
<span class="line"><span>│   ├── cmdline</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>如果以 root 权限运行这条命令（<code>sudo tree /proc</code>），你将会看到更多详细信息，因为 <code>/proc</code> 目录的许多内容对于普通用户而言是无法访问的。</p><p>命令 <code>tree -d</code> 将会限制仅显示目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree -d /proc</span></span>
<span class="line"><span>/proc</span></span>
<span class="line"><span>├── 1</span></span>
<span class="line"><span>│   ├── attr</span></span>
<span class="line"><span>│   │   ├── apparmor</span></span>
<span class="line"><span>│   │   └── smack</span></span>
<span class="line"><span>│   ├── fd [error opening dir]</span></span>
<span class="line"><span>│   ├── fdinfo [error opening dir]</span></span>
<span class="line"><span>│   ├── map_files [error opening dir]</span></span>
<span class="line"><span>│   ├── net</span></span>
<span class="line"><span>│   │   ├── dev_snmp6</span></span>
<span class="line"><span>│   │   ├── netfilter</span></span>
<span class="line"><span>│   │   └── stat</span></span>
<span class="line"><span>│   ├── ns [error opening dir]</span></span>
<span class="line"><span>│   └── task</span></span>
<span class="line"><span>│       └── 1</span></span>
<span class="line"><span>│           ├── attr</span></span>
<span class="line"><span>│           │   ├── apparmor</span></span>
<span class="line"><span>│           │   └── smack</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>使用 <code>-f</code> 选项，<code>tree</code> 命令会显示完整的路径。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree -f /proc</span></span>
<span class="line"><span>/proc</span></span>
<span class="line"><span>├── /proc/1</span></span>
<span class="line"><span>│   ├── /proc/1/attr</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/apparmor</span></span>
<span class="line"><span>│   │   │   ├── /proc/1/attr/apparmor/current</span></span>
<span class="line"><span>│   │   │   ├── /proc/1/attr/apparmor/exec</span></span>
<span class="line"><span>│   │   │   └── /proc/1/attr/apparmor/prev</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/current</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/display</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/exec</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/fscreate</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/keycreate</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/prev</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/smack</span></span>
<span class="line"><span>│   │   │   └── /proc/1/attr/smack/current</span></span>
<span class="line"><span>│   │   └── /proc/1/attr/sockcreate</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>分层显示通常可以使进程和文件之间的关系更容易理解。可用选项的数量很多，而你总可以找到一些视图，帮助你查看所需的内容。</p><hr>`,33)),a("p",null,[s[9]||(s[9]=n("via: ",-1)),e(p,{href:"https://www.networkworld.com/article/3444589/viewing-files-and-processes-as-trees-on-linux.html"},{default:i(()=>[...s[8]||(s[8]=[n("https://www.networkworld.com/article/3444589/viewing-files-and-processes-as-trees-on-linux.html",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=n("作者：",-1)),e(p,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[10]||(s[10]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[15]||(s[15]=n(" 选题：",-1)),e(p,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[11]||(s[11]=[n("lujun9972",-1)])]),_:1}),s[16]||(s[16]=n(" 译者：",-1)),e(p,{href:"https://github.com/laingke"},{default:i(()=>[...s[12]||(s[12]=[n("laingke",-1)])]),_:1}),s[17]||(s[17]=n(" 校对：",-1)),e(p,{href:"https://github.com/wxy"},{default:i(()=>[...s[13]||(s[13]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[20]||(s[20]=n("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[18]||(s[18]=[n("LCTT",-1)])]),_:1}),s[21]||(s[21]=n(" 原创编译，",-1)),e(p,{href:"https://linux.cn/"},{default:i(()=>[...s[19]||(s[19]=[n("Linux中国",-1)])]),_:1}),s[22]||(s[22]=n(" 荣誉推出",-1))])])}const C=l(c,[["render",h]]);export{y as __pageData,C as default};
